SELECT id, customer_id, browser, FIRST_VALUE(country, TRUE) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY device, customer_id ORDER BY started_at, id) AS event_seq, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY device, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country FROM sessions WHERE HOUR(started_at) BETWEEN 8 AND 14;
